contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10, "ticket must be exactly 10 wei");
        require(address(this).balance >= amount, "insufficient balance");

        uint256 beforeC = address(c).balance;
        uint256 beforeSender = address(this).balance;

        c.play{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 afterC = address(c).balance;
        assert(afterC == beforeC || afterC == beforeC + 10);
    }

    receive() external payable {}
}

